scenarios.example_code:
import { installConnector } from '@projexlight/connector-hubspot';
const { install_id } = await installConnector({
  tenant_id, hubspot_portal_id, auth_code,
});

import { registerBinding } from '@projexlight/connector-hubspot';
await registerBinding({
  install_id, projex_entity: 'sdk-lead-scoring.lead_score',
  hubspot_object: 'Contact', hubspot_field_map: { score: 'projex_lead_score' },
  direction: 'push', cadence_min: 15,
});

import { handleWebhook } from '@projexlight/connector-hubspot';
await handleWebhook({
  tenant_id, signature, body, event_type: 'deal.creation',
});

import { registerBinding } from '@projexlight/connector-hubspot';
await registerBinding({
  install_id, projex_entity: 'contact-cache',
  hubspot_object: 'Contact', direction: 'pull', cadence_min: 1440,
});
